SELECT *
FROM iam_role_assignments
WHERE principal_id = #{principalId}
  AND assignment_status = 'ACTIVE'
  AND valid_from <= #{now}
  AND (valid_until IS NULL OR valid_until > #{now})

SELECT COUNT(*)
FROM iam_role_assignments
WHERE role_id = #{roleId}
  AND assignment_status = 'ACTIVE'
  AND valid_from <= #{now}
  AND (valid_until IS NULL OR valid_until > #{now})

SELECT *
FROM iam_role_assignments
WHERE role_id = #{roleId}
  AND assignment_status = 'ACTIVE'
  AND valid_from <= #{now}
  AND (valid_until IS NULL OR valid_until > #{now})

SELECT COUNT(*)
FROM iam_role_assignments
WHERE role_id = #{roleId}
  AND assignment_status = 'ACTIVE'
  AND valid_from > #{now}

SELECT COUNT(*)
FROM iam_role_assignments
WHERE role_id = #{roleId}

SELECT ra.*
FROM iam_role_assignments ra

    JOIN iam_roles r ON r.role_id = ra.role_id


    AND ra.principal_id = #{principalId}
    AND ra.role_id = #{roleId}
    AND r.role_code = #{roleCode}
    AND ra.scope_type = #{scopeType}
    AND ra.scope_id = #{scopeId}
    AND ra.assignment_status = #{status}

ORDER BY ra.created_at DESC
LIMIT #{limit} OFFSET #{offset}
